const formatOptions=[['p','Обычный','bbf44'],['h2','Заголовок','8f12c'],['h3','Подзаголовок','8f12c'],['ol','Нумерованный список','list-ordered'],['ul','Маркированный список','65f9f'],['blockquote','Цитата','quote'],['pre','Код','c5d74']];
