function applyTextFormat(value){if(!restore())return;const active=currentFormat();if(active===value){hidePopup();updateActive();return;}pushHistory();document.execCommand('styleWithCSS',false,false);if(value==='ol'||value==='ul'){document.execCommand('formatBlock',false,'p');document.execCommand(value==='ol'?'insertOrderedList':'insertUnorderedList',false,null);}else{const wasList=active==='ol'||active==='ul';if(wasList)document.execCommand(active==='ol'?'insertOrderedList':'insertUnorderedList',false,null);if(!wasList||value!=='p')document.execCommand('formatBlock',false,value);}remember();changed();hidePopup();updateActive();}
