function colors(anchor,mode,block=null){const palette=mode==='color'?['#1c1c1e','#5a5e62','#8a8e93','#d53d3d','#bd6a18','#348158','#2b74bd','#7460ce','#a9408e','#ffffff','#000000','#a3965c']:['#ffffff','#f0f1f3','#e9e5ff','#dfeeff','#e2f4e7','#fff2cc','#ffe6dd','#fce0ef','#ddd5ff','#c6ebf0','#e7f0c5','#d6d6d6'];showPopup(`<div class="menu-title">${block?'Цвет фона инфоблока':mode==='color'?'Цвет текста':'Цвет фона текста'}</div><div class="swatches">${palette.map(c=>`<button class="swatch" data-color="${c}" style="background:${c}" title="${c}" aria-label="Цвет ${c}"></button>`).join('')}</div><label class="custom-color">Другой цвет <input type="color" id="custom-color" value="${palette[0]}"></label><button class="menu-item" data-color="reset">Сбросить цвет</button>`,anchor,240,'color');popup.colorMode=mode;popup.targetBlock=block;}
function applyColor(c){if(popup.targetBlock){pushHistory();popup.targetBlock.style.backgroundColor=c==='reset'?'#e9e5ff':c;changed();}else command(popup.colorMode==='color'?'foreColor':'hiliteColor',c==='reset'?(popup.colorMode==='color'?'#1c1c1e':'transparent'):c);hidePopup();}
let editingLink=null,editingAnchor=null;
function selectionElement(selector){if(!savedRange?.startContainer.isConnected)return null;const node=parentElement(savedRange.startContainer)?.closest(selector);return node&&editor.contains(node)?node:null;}
function selectContents(node){const r=document.createRange();r.selectNodeContents(node);savedRange=r;const selection=getSelection();selection.removeAllRanges();selection.addRange(r);}
function anchorTargets(){return [...editor.querySelectorAll('[data-anchor],span[id^="anchor-"]')];}
function linkPopup(anchor,link=null){editingLink=link||selectionElement('a:not([download])');if(editingLink)selectContents(editingLink);const targets=anchorTargets(),value=editingLink?.getAttribute('href')||'';showPopup(`<form id="link-form"><div class="field"><label for="url">Адрес ссылки</label><input id="url" name="url" type="text" value="${esc(value)}" placeholder="https://example.com или #razdel-1" required></div>${targets.length?`<div class="field"><label for="link-anchor">Якорь на этой странице</label><select id="link-anchor"><option value="">Выберите якорь</option>${targets.map(n=>`<option value="${esc(n.id)}" ${value==='#'+n.id?'selected':''}>${esc(n.id)}</option>`).join('')}</select></div>`:''}<div class="actions">${editingLink?'<button type="button" class="secondary" data-choice="follow-link">Перейти</button><button type="button" class="secondary" data-choice="unlink">Убрать ссылку</button>':''}<button class="primary" type="submit">Применить</button></div></form>`,anchor,380,'link');$('#url').focus();}
function unlinkCurrent(){if(editingLink?.isConnected){pushHistory();const link=editingLink,parent=link.parentElement;link.replaceWith(...link.childNodes);editingLink=null;savedRange=null;caret(parent,true);changed();}else command('unlink');hidePopup();}
function followLink(link=editingLink){if(!link?.isConnected)return;const href=link.getAttribute('href')||'';if(href.startsWith('#')){let id;try{id=decodeURIComponent(href.slice(1));}catch{id=href.slice(1);}const target=[...editor.querySelectorAll('[id]')].find(n=>n.id===id);if(!target){toast('Якорь не найден на странице');return;}hidePopup();bubble.hidden=true;target.scrollIntoView({block:'center',behavior:'instant'});target.classList.add('anchor-flash');setTimeout(()=>target.classList.remove('anchor-flash'),1500);}else if(/^(https?:|mailto:|tel:)/i.test(href))window.open(href,'_blank','noopener');}
function anchorPopup(anchor,node=null){editingAnchor=node||selectionElement('[data-anchor],span[id^="anchor-"]');if(!savedRange&&!editingAnchor){toast('Сначала поставьте курсор в текст');return;}const value=editingAnchor?.id||'';showPopup(`<form id="anchor-form"><div class="field"><label for="anchor-name">Имя якоря</label><input id="anchor-name" value="${esc(value)}" placeholder="razdel-1" required><div class="anchor-hint">Буквы, цифры, дефис или подчеркивание. Ссылка на этот якорь: #имя</div><div id="anchor-error" class="form-error" role="alert"></div></div><div class="actions">${editingAnchor?'<button type="button" class="secondary" data-choice="remove-anchor">Убрать якорь</button>':''}<button class="primary" type="submit">Сохранить</button></div></form>`,anchor,360,'anchor');$('#anchor-name').focus();}
function removeAnchor(){const node=editingAnchor;if(!node?.isConnected)return;pushHistory();editor.querySelectorAll('a[href]').forEach(a=>{if(a.getAttribute('href')==='#'+node.id)a.replaceWith(...a.childNodes);});if(node.classList.contains('anchor-point'))node.remove();else node.replaceWith(...node.childNodes);editingAnchor=null;savedRange=null;hidePopup();changed();}
function saveAnchor(){const name=$('#anchor-name').value.trim(),error=$('#anchor-error');if(!/^[\p{L}_][\p{L}\p{N}_.:-]*$/u.test(name)){error.textContent='Начните с буквы. Используйте буквы, цифры, дефис или подчеркивание.';return;}if([...document.querySelectorAll('[id]')].some(n=>n.id===name&&n!==editingAnchor)){error.textContent='Такое имя уже есть. Выберите другое.';return;}if(editingAnchor?.isConnected){pushHistory();const old=editingAnchor.id;editingAnchor.id=name;editingAnchor.dataset.anchor='true';editingAnchor.classList.add('anchor-target');editingAnchor.title='Якорь: '+name;if(editingAnchor.classList.contains('anchor-point'))editingAnchor.setAttribute('aria-label','Якорь: '+name);editor.querySelectorAll('a[href]').forEach(a=>{if(a.getAttribute('href')==='#'+old)a.setAttribute('href','#'+name);});}else{if(!restore()){toast('Сначала поставьте курсор в текст');return;}pushHistory();const r=getSelection().getRangeAt(0),node=document.createElement('span');node.id=name;node.dataset.anchor='true';node.className='anchor-target';node.title='Якорь: '+name;if(!r.collapsed&&topBlock(r.startContainer)===topBlock(r.endContainer)){node.append(r.extractContents());r.insertNode(node);selectContents(node);}else{r.collapse(true);node.classList.add('anchor-point');node.contentEditable='false';node.innerHTML=img(icons.anchor);node.setAttribute('aria-label','Якорь: '+name);r.insertNode(node);r.setStartAfter(node);r.collapse(true);savedRange=r.cloneRange();getSelection().removeAllRanges();getSelection().addRange(r);}}hidePopup();changed();toast('Якорь сохранен');}

function commentIdentity(message){const own=isOwnComment(message);const login=own?currentUser.login:message.author;return {login,avatar:own?`<img class="comment-avatar" src="${currentUser.avatar}" alt="">`:`<span class="comment-avatar initials" aria-hidden="true">${esc(login.slice(0,1).toUpperCase())}</span>`};}
function commentPopup(anchor,id=null){currentThread=id;const thread=id?comments[id]:null;showPopup(`<div class="menu-title">${thread?'Комментарии':'Новый комментарий'}</div>${thread?thread.messages.map((m,index)=>{const user=commentIdentity(m);return `<div class="comment-card"><div class="comment-author">${user.avatar}<span class="comment-login">${esc(user.login)}</span><time>${new Date(m.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time></div><div class="comment-body">${esc(m.text)}${m.editedAt?'<span class="comment-edited">Изменён</span>':''}</div><div class="comment-message-actions">${isOwnComment(m)?`<button class="edit-comment" type="button" data-edit-comment="${index}" aria-label="Редактировать комментарий" title="Редактировать комментарий"><img src="assets/edit-comment.svg" width="20" height="20" alt=""></button>`:''}<button class="delete-comment" data-delete-comment="${index}" aria-label="Удалить комментарий" title="Удалить комментарий"><img src="assets/trash.svg" width="20" height="20" alt=""></button></div></div>`;}).join(''):''}${thread?`<div class="field"><div class="comment-quote">${esc(thread.quote)}</div></div>`:''}<form id="comment-form"><div class="composer-user"><img class="comment-avatar" src="${currentUser.avatar}" alt=""><div><span class="comment-login">${esc(currentUser.login)}</span><span class="composer-you">Вы</span></div></div><div class="field"><label for="comment-text">${thread?'Ответ':'Комментарий'}</label><textarea id="comment-text" required placeholder="Напишите комментарий"></textarea></div><div class="actions"><button type="button" class="secondary" data-choice="close">Закрыть</button><button class="primary">${thread?'Ответить':'Добавить'}</button></div></form>`,anchor,320,'comment');$('#comment-text').focus();}

function deleteComment(index){const id=currentThread,thread=comments[id];if(!thread||!Number.isInteger(index)||index<0||index>=thread.messages.length)return;const reply=$('#comment-text')?.value||'';pushHistory();thread.messages.splice(index,1);const marks=[...editor.querySelectorAll('[data-comment-id]')].filter(n=>n.dataset.commentId===id);if(!thread.messages.length){for(const mark of marks)mark.replaceWith(...mark.childNodes);delete comments[id];currentThread=null;savedRange=null;closeSelection();changed();}else{changed();commentPopup(marks[0]||$('#more'),id);$('#comment-text').value=reply;}toast('Комментарий удален');}
function allComments(anchor){const active=Object.entries(comments).filter(([id])=>editor.querySelector(`[data-comment-id="${id}"]`));showPopup('<div class="menu-title">Комментарии к тексту</div>'+(active.length?active.map(([id,t])=>`<button class="menu-item" data-thread="${id}"><span>${esc(t.quote.slice(0,65))}</span><small>${t.messages.length}</small></button>`).join(''):'<div class="empty-note">Комментариев пока нет. Выделите текст и нажмите «Комментарий».</div>'),anchor,320,'threads');}
function upload(kind){uploadKind=kind;const input=$('#upload');input.accept={image:'image/*',video:'video/*',audio:'audio/*',file:'*/*'}[kind];input.value='';hidePopup();input.click();}
async function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
function fileSizeLabel(bytes){const units=['Б','КБ','МБ','ГБ'];let size=Math.max(0,bytes),unit=0;while(size>=1024&&unit<units.length-1){size/=1024;unit++;}return new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(size)+' '+units[unit];}
function attachmentHTML(src,name,size){return `<div class="block media-file file-attachment" contenteditable="false" data-file-size="${size}">${blockControls()}<span class="file-icon"><img src="assets/attachment-file.svg" width="24" height="24" alt=""></span><div class="file-details"><a class="file-name" href="${esc(src)}" download="${esc(name)}" title="${esc(name)}">${esc(name)}</a><span class="file-size">${fileSizeLabel(size)}</span></div></div>`;}
function upgradeAttachments(){editor.querySelectorAll('.file-attachment .file-download').forEach(button=>button.remove());for(const old of editor.querySelectorAll('.media-file:not(.file-attachment)')){const link=old.querySelector('a[download]');if(!link)continue;const src=link.getAttribute('href')||'',name=link.getAttribute('download')||link.textContent.trim();let size=0;if(src.startsWith('data:')){const comma=src.indexOf(','),payload=src.slice(comma+1);if(src.slice(0,comma).includes(';base64'))size=Math.max(0,Math.floor(payload.length*3/4)-(payload.endsWith('==')?2:payload.endsWith('=')?1:0));else try{size=new Blob([decodeURIComponent(payload)]).size;}catch{size=0;}}const t=document.createElement('template');t.innerHTML=attachmentHTML(src,name,size);old.replaceWith(t.content);}}
async function insertFiles(files,kind){for(const file of files){try{const src=await readFile(file);if(kind==='image'||file.type.startsWith('image/')){if(!file.type.startsWith('image/')){toast('Выберите изображение');continue;}insertBlock(imageHTML(src,file.name));}else if(kind==='video'||kind==='audio'){if(!file.type.startsWith(kind+'/')){toast(`Выберите ${names[kind].toLowerCase()}`);continue;}insertBlock(`<div class="block media-file" contenteditable="false">${blockControls()}<${kind} src="${esc(src)}" controls></${kind}></div>`);}else insertBlock(attachmentHTML(src,file.name,file.size));}catch{toast('Не удалось прочитать файл. Выберите его еще раз.');}}}
function addMenu(){if(add.disabled)return;if(menuKind==='add'&&!popup.hidden){hidePopup();return;}remember();if(!savedRange)caret(editor.firstElementChild);const items=[['Текст'],['new:p','Обычный','bbf44'],['new:h2','Заголовок','8f12c'],['new:h3','Подзаголовок','8f12c'],['new:list','Список','65f9f'],['new:quote','Цитата','quote'],['new:code','Код','c5d74'],['action:latex','Формула LaTeX','formula'],['Стандартные блоки'],['new:divider','Разделитель','1f6f1'],['new:info','Инфоблок','badec'],['action:synced','Синхронизируемый блок','synced'],['new:table','Таблица','3db6e'],['action:columns','Колонки','39370'],['new:accordion','Аккордеон','b54bf'],['Медиа'],['upload:file','Файл','78d14'],['upload:image','Изображение','9339c'],['upload:video','Видео','49d8a'],['upload:audio','Аудио','6a894']];const rect=add.getBoundingClientRect();showPopup(items.map(i=>i.length===1?`<div class="menu-title">${i[0]}</div>`:menuItem(...i)).join(''),{left:editor.getBoundingClientRect().left,bottom:rect.top-5},280,'add');add.setAttribute('aria-expanded','true');}
function newBlock(type){const html={p:'<p><br></p>',h2:'<h2>Заголовок</h2>',h3:'<h3>Подзаголовок</h3>',list:'<ol><li><br></li></ol>',quote:'<blockquote><br></blockquote>',code:'<pre><br></pre>',divider:'<hr contenteditable="false">',info:infoHTML(),columns:columnsHTML(),table:'<table><tbody><tr><td><br></td><td><br></td></tr><tr><td><br></td><td><br></td></tr></tbody></table>',accordion:accordionHTML()}[type];insertBlock(html);if(['p','h2','h3','quote','code','list'].includes(type)){let prev=parentElement(savedRange.startContainer)?.previousElementSibling;if(prev){caret(prev);if(type==='h2'||type==='h3'){const r=document.createRange();r.selectNodeContents(prev);getSelection().removeAllRanges();getSelection().addRange(r);remember();}}}}
function action(key,anchor){remember();if(['file','image','audio','video'].includes(key))return upload(key);switch(key){case'undo':return undo();case'redo':return redo();case'format':return chooseFormat(anchor);case'text':return showPopup(['bold','italic','underline','strike'].map(k=>menuItem('action:'+k,names[k],icons[k])).join(''),anchor,230,'text');case'align':return showPopup(['Left','Center','Right','Full'].map((k,i)=>menuItem('align:'+k,['По левому краю','По центру','По правому краю','По ширине'][i],icons.align)).join(''),anchor,230,'align');case'list':return showPopup(menuItem('list:ordered','Нумерованный список',icons.list)+menuItem('list:unordered','Маркированный список',icons.list),anchor,270,'list');case'color':case'highlight':return colors(anchor,key);case'link':return linkPopup(anchor);case'comment':if(!savedRange||savedRange.collapsed)return allComments(anchor);return commentPopup(anchor);case'quote':return command('formatBlock','blockquote');case'code':return command('formatBlock','pre');case'latex':return formulaPopup(anchor);case'anchor':return anchorPopup(anchor);case'synced':return chooseSyncedBlock(anchor);case'columns':return chooseColumns(anchor);case'divider':case'info':case'table':case'accordion':return newBlock(key);default:{const cmd={bold:'bold',italic:'italic',underline:'underline',strike:'strikeThrough',sub:'subscript',sup:'superscript',clear:'removeFormat'}[key];if(cmd)command(cmd);}}}
document.addEventListener('pointerdown',e=>{if(e.target.closest('#toolbar,#bubble,#add')||e.target.closest('[data-sync-action],.menu-item,.swatch,[data-block-action],[data-accordion-action],[data-info-emoji],[data-emoji-choice],[data-image-align-choice],[data-restore-caption]')){remember();e.preventDefault();}else if(!e.target.closest('#popup'))hidePopup();});
document.addEventListener('click',e=>{const syncAction=e.target.closest('[data-sync-action]');if(syncAction){handleSyncedAction(syncAction);return;}if(e.target.closest('[data-sync-create]')){createSyncedBlock();return;}if(e.target.closest('[data-sync-empty]')){createSyncedBlock(true);return;}const syncInsert=e.target.closest('[data-sync-insert]');if(syncInsert){insertSyncedBlock(syncInsert.dataset.syncInsert);return;}const captionButton=e.target.closest('[data-restore-caption]');if(captionButton){restoreCaption(captionButton);return;}const imageAlign=e.target.closest('[data-image-align-choice]');if(imageAlign){alignImage(imageAlign.closest('.media'),imageAlign.dataset.imageAlignChoice);return;}const emojiButton=e.target.closest('[data-info-emoji]');if(emojiButton){chooseInfoEmoji(emojiButton);return;}const emojiChoice=e.target.closest('[data-emoji-choice]');if(emojiChoice){applyInfoEmoji(emojiChoice.dataset.emojiChoice);return;}const formula=e.target.closest('.latex-render');if(formula){formulaPopup(formula,formula.closest('.latex-block'));return;}const b=e.target.closest('[data-action]');if(b){action(b.dataset.action,b);return;}const choice=e.target.closest('[data-choice]');if(choice){const [kind,value]=choice.dataset.choice.split(':');if(kind==='action'){hidePopup();action(value,choice);}else if(kind==='format')applyTextFormat(value);else if(kind==='align'){command('justify'+value);hidePopup();}else if(kind==='list'){command(value==='ordered'?'insertOrderedList':'insertUnorderedList');hidePopup();}else if(kind==='columns')insertBlock(columnsHTML('','',Number(value)));else if(kind==='new')newBlock(value);else if(kind==='upload')upload(value);else if(kind==='unlink')unlinkCurrent();else if(kind==='follow-link')followLink();else if(kind==='remove-anchor')removeAnchor();else if(kind==='close')hidePopup();else if(kind==='scenario'){setScenario(value);hidePopup();}else if(kind==='threads')allComments($('#more'));else if(kind==='pdf')exportPDF();else if(kind==='export')exportDraft();else if(kind==='import'){uploadDraft();}return;}
const edit=e.target.closest('[data-edit-comment]');if(edit){editComment(Number(edit.dataset.editComment));return;}if(e.target.closest('[data-cancel-comment-edit]')){refreshComments();return;}const deletion=e.target.closest('[data-delete-comment]');if(deletion){deleteComment(Number(deletion.dataset.deleteComment));return;}
const color=e.target.closest('[data-color]');if(color){applyColor(color.dataset.color);return;}const thread=e.target.closest('[data-thread]');if(thread){const mark=editor.querySelector(`[data-comment-id="${thread.dataset.thread}"]`);mark?.scrollIntoView({block:'center'});commentPopup(mark||$('#more'),thread.dataset.thread);return;}
const accordionAction=e.target.closest('[data-accordion-action]');if(accordionAction){e.preventDefault();const block=accordionAction.closest('.accordion');if(!block)return;pushHistory();if(accordionAction.dataset.accordionAction==='delete'){block.remove();savedRange=null;}else{block.open=!block.open;const toggle=block.querySelector('[data-accordion-action="toggle"]');toggle.setAttribute('aria-expanded',String(block.open));toggle.setAttribute('aria-label',(block.open?'Свернуть':'Развернуть')+' аккордеон');toggle.title=(block.open?'Свернуть':'Развернуть')+' аккордеон';if(!block.open)caret(block.querySelector('.accordion-title'));}changed();return;}
const ba=e.target.closest('[data-block-action]');if(ba){const block=ba.closest('.block');if(ba.dataset.blockAction==='delete'){pushHistory();block.remove();changed();}else colors(ba,'highlight',block);return;}
const mark=e.target.closest('[data-comment-id]');if(mark){commentPopup(mark,mark.dataset.commentId);return;}if(e.target.closest('a')&&editor.contains(e.target)){const a=e.target.closest('a');if(a.hasAttribute('download'))return;e.preventDefault();if(e.metaKey||e.ctrlKey)followLink(a);else{remember();linkPopup(a,a);}return;}const anchorMark=e.target.closest('[data-anchor],span[id^="anchor-"]');if(anchorMark&&editor.contains(anchorMark)){remember();anchorPopup(anchorMark,anchorMark);return;}
selectMedia(e.target.closest('.media'));});
