function selectMedia(media){selectedMedia?.classList.remove('selected');selectedMedia=media;media?.classList.add('selected');}
$('#custom-color')?.addEventListener('change',e=>applyColor(e.target.value));
popup.addEventListener('change',e=>{if(e.target.id==='custom-color')applyColor(e.target.value);if(e.target.id==='link-anchor'&&e.target.value)$('#url').value='#'+e.target.value;});
popup.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='delete-section-form'){deleteSection(e.target);return;}if(e.target.id==='section-form'){addSection(e.target);return;}if(e.target.id==='move-article-form'){const item=popup.movingItem,[courseId,topicId]=$('#move-article-target').value.split(':');if(item)moveArticle(item.id,courseId,topicId);return;}if(e.target.id==='delete-topic-form'){deleteTreeItem('topic',e.target.dataset.courseId,e.target.dataset.topicId);return;}if(e.target.id==='topic-form'){addTopic(e.target);return;}if(e.target.matches('.comment-edit-form')){saveCommentEdit(e.target);return;}if(e.target.id==='formula-form'){saveFormula();return;}if(e.target.id==='anchor-form'){saveAnchor();return;}if(e.target.id==='link-form'){let url=$('#url').value.trim();if(!url)return;if(/^[a-z][a-z0-9+.-]*:/i.test(url)&&! /^(https?:|mailto:|tel:)/i.test(url)){toast('Введите адрес http, https, email или якорь');return;}if(!/^(https?:\/\/|mailto:|tel:|#)/i.test(url))url='https://'+url;if(editingLink?.isConnected){pushHistory();editingLink.setAttribute('href',url);changed();hidePopup();return;}if(!savedRange||savedRange.collapsed){toast('Сначала выделите текст для ссылки');return;}command('createLink',url);hidePopup();}

if(e.target.id==='comment-form'){const text=$('#comment-text').value.trim();if(!text)return;pushHistory();const m={author:currentUser.login,authorId:currentUser.id,text,at:Date.now()};let id=currentThread;if(id){comments[id].messages.push(m);}else{if(!restore()||savedRange.collapsed){toast('Сначала выделите текст для комментария');return;}id='c'+Date.now().toString(36);const quote=savedRange.toString();comments[id]={quote,messages:[m]};inlineWrap('span',{'class':'comment-mark','data-comment-id':id});}changed();const mark=editor.querySelector(`[data-comment-id="${id}"]`);commentPopup(mark||$('#more'),id);}});
