function columnIsEmpty(column){return !column.textContent.replace(/[\s\u200B-\u200D\uFEFF]/g,'')&&!column.querySelector('img,video,audio,table,hr,.block');}
function ordinaryColumnContent(column){const fragment=document.createDocumentFragment();let paragraph=null;const flush=()=>{paragraph=null;};const appendInline=node=>{if(!paragraph){paragraph=document.createElement('p');fragment.append(paragraph);}paragraph.append(node.cloneNode(true));};const visit=nodes=>{for(const node of nodes){if(node.nodeType===3){appendInline(node);continue;}if(node.nodeType!==1)continue;if(node.matches('.block,table,hr')){flush();fragment.append(node.cloneNode(true));continue;}if(node.matches('p,h1,h2,h3,h4,h5,h6,li')){flush();paragraph=document.createElement('p');fragment.append(paragraph);visit([...node.childNodes]);if(!paragraph?.hasChildNodes()&&fragment.lastElementChild?.tagName==='P')fragment.lastElementChild.append(document.createElement('br'));flush();}else if(node.matches('div,blockquote,pre,ul,ol')){flush();visit([...node.childNodes]);flush();}else appendInline(node);}};visit([...column.childNodes]);if(!fragment.hasChildNodes()){const p=document.createElement('p');p.append(document.createElement('br'));fragment.append(p);}return fragment;}
