// Print a separate snapshot so expanding accordions never changes the draft.
async function exportPDF(){
 if(exportPDF.busy)return;
 exportPDF.busy=true;hidePopup();bubble.hidden=true;
 let frame;
 try{
  const copy=editor.cloneNode(true);
  copy.className='';copy.querySelectorAll('.synced-heading').forEach(n=>n.remove());copy.querySelectorAll('.synced-block').forEach(n=>n.classList.add('synced-print'));
  copy.querySelectorAll('button.info-emoji').forEach(button=>{const icon=document.createElement('span');icon.className='info-emoji';icon.textContent=button.textContent;button.replaceWith(icon);});
  copy.querySelectorAll('.block-controls,.accordion-actions,.resize-handle,.anchor-point,button').forEach(n=>n.remove());
  copy.querySelectorAll('[contenteditable]').forEach(n=>n.removeAttribute('contenteditable'));copy.removeAttribute('contenteditable');
  copy.querySelectorAll('.selected,.is-empty,.drag-source,.anchor-flash').forEach(n=>n.classList.remove('selected','is-empty','drag-source','anchor-flash'));
  copy.querySelectorAll('details').forEach(n=>n.open=true);
  copy.querySelectorAll('video,audio').forEach(n=>{const note=document.createElement('p');note.className='pdf-media-note';note.textContent=n.tagName==='VIDEO'?'Видео (доступно в редакторе)':'Аудио (доступно в редакторе)';n.replaceWith(note);});
  copy.querySelectorAll('a[download]').forEach(n=>n.removeAttribute('href'));
  const heading=title.innerText.trim(),filename=heading||'Новая страница';
  frame=document.createElement('iframe');frame.title='Печатная версия страницы';frame.setAttribute('aria-hidden','true');
  frame.style.cssText='position:fixed;left:-20000px;top:0;width:1050px;height:800px;border:0;pointer-events:none';
  const ready=new Promise((resolve,reject)=>{frame.onload=resolve;frame.onerror=()=>reject(Error('print load'));});
  frame.srcdoc=`<!doctype html><html lang="ru"><head><meta charset="utf-8"><base href="${esc(document.baseURI)}"><title>${esc(filename)}</title><link rel="stylesheet" href="style.css?v=article-menu-type"><link rel="stylesheet" href="assets/katex/katex.min.css"><link rel="stylesheet" href="pdf.css"></head><body class="pdf-page"><main>${heading?`<h1>${esc(heading)}</h1>`:''}${copy.outerHTML}</main></body></html>`;
  document.body.append(frame);await ready;
  const doc=frame.contentDocument;
  await doc.fonts.ready;
  await Promise.all([...doc.images].map(n=>n.decode().catch(()=>{})));
  await new Promise(resolve=>frame.contentWindow.requestAnimationFrame(()=>frame.contentWindow.requestAnimationFrame(resolve)));
  frame.contentWindow.addEventListener('afterprint',()=>{frame.remove();exportPDF.busy=false;},{once:true});
  frame.contentWindow.focus();frame.contentWindow.print();
  // Keep the snapshot alive while the native print preview is open.
  setTimeout(()=>{frame.remove();exportPDF.busy=false;},300000);
 }catch{frame?.remove();exportPDF.busy=false;toast('Не удалось подготовить PDF. Попробуйте ещё раз.');}
}
function sanitizeHTML(html){const template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('script,style,iframe,object,embed,link,meta,form,input,textarea').forEach(e=>e.remove());template.content.querySelectorAll('*').forEach(e=>{for(const a of [...e.attributes]){if(a.name.startsWith('on')||a.name==='srcdoc'||(['href','src'].includes(a.name)&&!(a.name==='href'&&e.tagName==='A'&&e.hasAttribute('download')&&a.value.startsWith('data:'))&&!(/^(https?:|mailto:|tel:|#|assets\/|data:image\/|data:audio\/|data:video\/)/i.test(a.value))))e.removeAttribute(a.name);}});return template.innerHTML;}
function uploadDraft(){hidePopup();const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const s=JSON.parse(await input.files[0].text());if(typeof s.html!=='string'||typeof s.title!=='string')throw Error();pushHistory();s.html=sanitizeHTML(s.html);const safe={};for(const [id,t]of Object.entries(s.comments||{})){if(!/^c[a-z0-9]+$/.test(id)||!Array.isArray(t.messages))continue;safe[id]={quote:String(t.quote||''),messages:t.messages.map(m=>({author:String(m.author||'Редактор'),authorId:String(m.authorId||''),text:String(m.text||''),at:Number(m.at)||Date.now(),editedAt:Number(m.editedAt)||undefined}))};}s.comments=safe;applyState(s);pushHistory();toast('Черновик открыт');}catch{toast('Не удалось открыть черновик. Выберите JSON-файл, скачанный из редактора.');}};input.click();}
let editingFormula=null;
const formulaOptions={displayMode:true,throwOnError:true,trust:false,strict:'ignore',maxExpand:1000,maxSize:20,output:'htmlAndMathml'};
function formulaSource(value){return value.trim().replace(/^\$\$([\s\S]*)\$\$$/,'$1').replace(/^\\\[([\s\S]*)\\\]$/,'$1').trim();}
function formulaMode(){return $('#formula-mode')?.value==='text'?'text':'formula';}
function mixedFormulaMarkup(source){
 let html='',plain='',i=0;
 const flush=()=>{if(plain){html+=`<span class="latex-plain">${esc(plain)}</span>`;plain='';}};
 while(i<source.length){
  if(source[i]==='\\'&&source[i+1]==='$'){plain+='$';i+=2;continue;}
  if(source[i]!=='$'){plain+=source[i++];continue;}
  flush();const display=source[i+1]==='$',delimiter=display?'$$':'$',start=i+delimiter.length;let end=start;
  for(;end<source.length;end++){
   if(source[end]==='\\'){end++;continue;}
   if(source.startsWith(delimiter,end))break;
  }
  if(end>=source.length)throw Error('delimiter');
  const expression=source.slice(start,end).trim();if(!expression)throw Error('empty formula');
  const rendered=katex.renderToString(expression,{...formulaOptions,displayMode:display});
  html+=display?`<div class="latex-display-formula">${rendered}</div>`:`<span class="latex-inline-formula">${rendered}</span>`;
  i=end+delimiter.length;
 }
 flush();return `<div class="latex-mixed">${html}</div>`;
}
function formulaMarkup(source,mode='formula'){return mode==='text'?mixedFormulaMarkup(source):katex.renderToString(source,formulaOptions);}
function formulaHTML(source,mode='formula'){return `<div class="block latex-block" contenteditable="false" data-latex-mode="${mode}" data-latex="${esc(source)}">${blockControls()}<div class="latex-render" role="button" tabindex="0" aria-label="Редактировать формулу LaTeX" title="Редактировать блок LaTeX">${formulaMarkup(source,mode)}</div></div>`;}
function renderLatexBlocks(){for(const block of editor.querySelectorAll('.latex-block')){const source=block.dataset.latex||'',mode=block.dataset.latexMode==='text'?'text':'formula';block.dataset.latexMode=mode;try{block.innerHTML=blockControls()+`<div class="latex-render" role="button" tabindex="0" aria-label="Редактировать формулу LaTeX" title="Редактировать блок LaTeX">${formulaMarkup(source,mode)}</div>`;}catch{block.innerHTML=blockControls()+`<div class="latex-render formula-invalid" role="button" tabindex="0" aria-label="Исправить формулу LaTeX">${esc(source)}<small>Нажмите, чтобы исправить блок</small></div>`;}}}
function formulaPopup(anchor,block=null){
 editingFormula=block;
 let anchorRect=anchor instanceof Element?anchor.getBoundingClientRect():anchor;if(!anchorRect?.width)anchorRect=add.getBoundingClientRect();
 const mode=block?.dataset.latexMode==='text'?'text':'formula';
 showPopup(`<div class="menu-title">${block?'Редактирование блока LaTeX':'Блок LaTeX'}</div><form id="formula-form"><div class="formula-scroll"><div class="field"><label for="formula-mode">Режим</label><select id="formula-mode"><option value="formula"${mode==='formula'?' selected':''}>Формула</option><option value="text"${mode==='text'?' selected':''}>Текст с формулами</option></select></div><div class="field"><label id="formula-source-label" for="formula-source">Код LaTeX</label><textarea id="formula-source" maxlength="5000" spellcheck="false" required>${esc(block?.dataset.latex||'')}</textarea><div id="formula-hint" class="anchor-hint"></div></div><div class="formula-examples"><button type="button" data-formula-example="fraction">Дробь</button><button type="button" data-formula-example="integral">Интеграл</button><button type="button" data-formula-example="matrix">Матрица</button></div><div class="field"><label>Предпросмотр</label><div id="formula-preview" class="formula-preview"></div><div id="formula-error" class="form-error" role="status"></div></div></div><div class="actions"><button type="button" class="secondary" data-choice="close">Отмена</button><button id="formula-save" class="primary" disabled>${block?'Сохранить':'Добавить'}</button></div></form>`,anchorRect,480,'formula');
 updateFormulaPreview();$('#formula-source').focus();
}
function updateFormulaPreview(){
 const field=$('#formula-source');if(!field)return;
 const mode=formulaMode(),source=mode==='text'?field.value:formulaSource(field.value),preview=$('#formula-preview'),error=$('#formula-error'),saveButton=$('#formula-save');
 $('#formula-source-label').textContent=mode==='text'?'Текст и формулы':'Код LaTeX';
 $('#formula-hint').textContent=mode==='text'?String.raw`Пробелы и переносы сохраняются. Формула в строке: $x^2$. Отдельная формула: $$x^2$$. Символ доллара: \$. Cmd/Ctrl + Enter — сохранить.`:String.raw`Введите формулу без $$ или \[ \]. Cmd/Ctrl + Enter — сохранить.`;
 field.placeholder=mode==='text'?'Введите текст. Формулы заключайте в $...$ или $$...$$.':String.raw`Например: \frac{a}{b}`;
 error.textContent='';saveButton.disabled=true;field.setAttribute('aria-invalid','false');
 if(!source.trim()){preview.textContent=mode==='text'?'Здесь появятся текст и формулы':'Здесь появится формула';preview.classList.add('placeholder');return;}
 preview.classList.remove('placeholder');
 try{preview.innerHTML=formulaMarkup(source,mode);saveButton.disabled=false;}catch{preview.textContent='';error.textContent=mode==='text'?'Проверьте команды, парные скобки и разделители $...$ или $$...$$.':'Не удалось отобразить формулу. Проверьте команды и парные скобки.';field.setAttribute('aria-invalid','true');}
}
function saveFormula(){const field=$('#formula-source');if(!field)return;const mode=formulaMode(),source=mode==='text'?field.value:formulaSource(field.value);if(!source.trim())return;try{const html=formulaHTML(source,mode);if(editingFormula?.isConnected){pushHistory();const t=document.createElement('template');t.innerHTML=html;editingFormula.dataset.latex=source;editingFormula.dataset.latexMode=mode;editingFormula.innerHTML=t.content.firstElementChild.innerHTML;hidePopup();changed();}else insertBlock(html);editingFormula=null;}catch{updateFormulaPreview();}}
popup.addEventListener('input',e=>{if(e.target.id==='formula-source')updateFormulaPreview();});
popup.addEventListener('change',e=>{if(e.target.id==='formula-mode')updateFormulaPreview();});
popup.addEventListener('click',e=>{const button=e.target.closest('[data-formula-example]');if(!button)return;const examples={fraction:String.raw`\frac{a}{b}`,integral:String.raw`\int_0^1 x^2\,dx = \frac{1}{3}`,matrix:String.raw`\begin{pmatrix} a & b \\ c & d \end{pmatrix}`};const field=$('#formula-source'),example=examples[button.dataset.formulaExample];if(formulaMode()==='text'){const start=field.selectionStart,end=field.selectionEnd,insert='$'+example+'$';field.value=field.value.slice(0,start)+insert+field.value.slice(end);field.setSelectionRange(start+insert.length,start+insert.length);}else field.value=example;updateFormulaPreview();field.focus();});
popup.addEventListener('keydown',e=>{if(e.target.id==='formula-source'&&(e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();if(!$('#formula-save').disabled)saveFormula();}});
