function infoEmojiButton(emoji){return `<button class="info-emoji" type="button" data-info-emoji aria-label="Выбрать эмодзи инфоблока" title="Выбрать эмодзи">${esc(emoji)}</button>`;}
function upgradeInfoEmojis(){for(const block of editor.querySelectorAll('.info')){const emoji=block.dataset.emoji||'💣';block.dataset.emoji=emoji;if(!block.querySelector(':scope > .info-emoji'))block.insertAdjacentHTML('afterbegin',infoEmojiButton(emoji));}}
function chooseInfoEmoji(button){const block=button.closest('.info');showPopup('<div class="menu-title">Эмодзи инфоблока</div><div class="emoji-grid">'+infoEmojis.map(([emoji,name])=>`<button type="button" class="emoji-choice" data-emoji-choice="${emoji}" aria-label="${name}" title="${name}" aria-pressed="${emoji===block.dataset.emoji}">${emoji}</button>`).join('')+'</div>',button,300,'emoji');popup.infoBlock=block;}
function applyInfoEmoji(emoji){const block=popup.infoBlock;if(!block?.isConnected||!infoEmojis.some(item=>item[0]===emoji))return;pushHistory();block.dataset.emoji=emoji;block.querySelector(':scope > .info-emoji').textContent=emoji;hidePopup();changed();}


const imageAlignments=[['left','По левому краю'],['center','По центру'],['right','По правому краю']];
function imageAlignmentButtons(selected='center'){return imageAlignments.map(([value,label])=>`<button class="icon-button" type="button" data-image-align-choice="${value}" aria-label="Изображение: ${label.toLowerCase()}" title="${label}" aria-pressed="${value===selected}"><img src="assets/image-align-${value}.svg" alt=""></button>`).join('');}
function setImageAlignment(block,value){block.dataset.imageAlign=value;block.style.marginLeft=value==='left'?'0':'auto';block.style.marginRight=value==='right'?'0':'auto';block.querySelectorAll('[data-image-align-choice]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.imageAlignChoice===value)));}
function upgradeImageAlignment(){for(const block of editor.querySelectorAll('.media')){if(!block.querySelector('.image-box'))continue;const value=imageAlignments.some(([v])=>v===block.dataset.imageAlign)?block.dataset.imageAlign:'center';const controls=block.querySelector(':scope > .block-controls');if(controls&&!controls.querySelector('[data-image-align-choice]'))controls.insertAdjacentHTML('afterbegin',imageAlignmentButtons(value));setImageAlignment(block,value);}}
function alignImage(block,value){if(!block||!imageAlignments.some(([v])=>v===value))return;pushHistory();setImageAlignment(block,value);changed();}

function isOwnComment(message){return message.authorId?message.authorId===currentUser.id:!message.author||message.author==='Редактор'||message.author===currentUser.login;}
function editComment(index){
 const message=comments[currentThread]?.messages[index];if(!message||!isOwnComment(message))return;
 const card=popup.querySelector(`[data-edit-comment="${index}"]`)?.closest('.comment-card');if(!card)return;
 card.querySelector('.comment-message-actions').style.display='none';
 card.querySelector('.comment-body').innerHTML=`<form class="comment-edit-form" data-message-index="${index}"><label for="comment-edit-${index}">Текст комментария</label><textarea id="comment-edit-${index}" required>${esc(message.text)}</textarea><div class="comment-edit-actions"><button type="button" class="secondary" data-cancel-comment-edit>Отмена</button><button class="primary" type="submit">Сохранить</button></div></form>`;
 const mark=editor.querySelector(`[data-comment-id="${currentThread}"]`);position(popup,(mark||$('#more')).getBoundingClientRect(),320);card.querySelector('textarea').focus();
}
function refreshComments(){const reply=$('#comment-text')?.value||'',id=currentThread,mark=editor.querySelector(`[data-comment-id="${id}"]`);commentPopup(mark||$('#more'),id);$('#comment-text').value=reply;}
function saveCommentEdit(form){const index=Number(form.dataset.messageIndex),message=comments[currentThread]?.messages[index],text=form.querySelector('textarea').value.trim();if(!message||!isOwnComment(message)||!text)return;if(text!==message.text){pushHistory();message.text=text;message.editedAt=Date.now();changed();}refreshComments();}

const courseCatalog=[
 {id:'backend',name:'Кампус',description:'Адреса корпусов, пространства и сервисы кампуса',topics:[
  {id:'web',name:'Основы веб-разработки',lessons:['Как работает веб','Роль бэкенда в веб-разработке']},
  {id:'django',name:'Знакомство с Django',lessons:['Первый проект Django','Модели и база данных','Представления и маршруты']},
  {id:'api',name:'API и публикация',lessons:['Основы REST API','Сериализация данных','Авторизация и права доступа','Публикация приложения']}]},
 {id:'math',name:'Учебный процесс',description:'Организация обучения, правила и учебные материалы',topics:[
  {id:'functions',name:'Функции и пределы',lessons:['Числовые функции','Предел и непрерывность']},
  {id:'derivatives',name:'Производная',lessons:['Определение производной','Правила дифференцирования','Исследование функций']},
  {id:'integrals',name:'Интегралы',lessons:['Первообразная','Неопределённый интеграл','Определённый интеграл','Применение интегралов']}]},
 {id:'design',name:'Другое',description:'Полезные контакты, ответы на вопросы и дополнительные материалы',topics:[
  {id:'research',name:'Исследования',lessons:['Постановка задачи','Интервью с пользователями']},
  {id:'interfaces',name:'Проектирование интерфейсов',lessons:['Пользовательские сценарии','Структура интерфейса','Интерактивный прототип']},
  {id:'testing',name:'Проверка решений',lessons:['Планирование теста','Проведение тестирования','Анализ результатов','Развитие продукта']}]}];
let currentLesson=null,navigationRunning=false;
const lessonCache=new Map();
function lessonContext(id){for(const [ci,course]of courseCatalog.entries())for(const [ti,topic]of articleContainers(course).entries())for(const [li,name]of topic.lessons.entries()){const key=topic.lessonIds[li];if(name!==null&&key===id)return{id:key,course,topic,name,number:`${ti+1}.${li+1}`,index:li,legacy:key==='backend-web-2'};}return null;}
function countLabel(count,forms){const n=count%100,last=count%10;return count+' '+(n>=11&&n<=14?forms[2]:last===1?forms[0]:last>=2&&last<=4?forms[1]:forms[2]);}
function treeAddButton(kind,courseId,topicId=''){return `<button class="tree-add" type="button" data-add-${kind}="${courseId}"${topicId?` data-topic-id="${topicId}"`:''}>${img('tree-plus')}<span>${kind==='topic'?'Тема':'Статья'}</span></button>`;}
function renderCourseTree(){
 ensureArticleIds();const tree=$('#course-tree'),openCourses=new Set([...tree.querySelectorAll('.course-node[open]')].map(n=>n.dataset.course)),openTopics=new Set([...tree.querySelectorAll('.topic-node[open]')].map(n=>n.dataset.topic));
 tree.innerHTML=courseCatalog.map((course,ci)=>`<details class="course-node" data-course="${course.id}"${openCourses.has(course.id)?' open':''}><summary><span class="tree-chevron" aria-hidden="true"></span><span class="course-badge" aria-hidden="true">${String(ci+1).padStart(2,'0')}</span><span class="course-summary"><strong>${esc(course.name)}</strong><span>${esc(course.description)}</span></span><span class="tree-count">${countLabel(course.topics.length,['тема','темы','тем'])} · ${countLabel(articleContainers(course).reduce((sum,t)=>sum+t.lessons.filter(n=>n!==null).length,0),['статья','статьи','статей'])}</span>${sectionDeleteButton(course)}</summary><div class="course-topics"><div class="section-articles" data-topic="direct">${renderArticleRows(course,course.directArticles)}</div>${course.topics.map((topic,ti)=>`<details class="topic-node" data-topic="${topic.id}"${openTopics.has(topic.id)?' open':''}><summary>${treeMoveHandle("topic",topic.id)}<span class="tree-chevron" aria-hidden="true"></span><span>${esc(topic.name)}</span><span class="tree-count">${countLabel(topic.lessons.filter(n=>n!==null).length,['статья','статьи','статей'])}</span>${treeDeleteButton('topic',course,topic)}</summary><div class="topic-lessons">${renderArticleRows(course,topic)}${treeAddButton('article',course.id,topic.id)}</div></details>`).join('')}<div class="section-add-actions">${treeAddButton('topic',course.id)}${treeAddButton('article',course.id,'direct')}</div></div></details>`).join('');
}
function saveCatalog(){if(!db)return Promise.reject(Error('storage unavailable'));return new Promise((resolve,reject)=>{const tx=db.transaction('draft','readwrite');tx.objectStore('draft').put(courseCatalog,'course-catalog');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function loadCatalog(){if(!db)return;const saved=await new Promise(resolve=>{const request=db.transaction('draft').objectStore('draft').get('course-catalog');request.onsuccess=()=>resolve(request.result);request.onerror=()=>resolve(null);});if(Array.isArray(saved)&&saved.every(c=>/^[a-z0-9-]+$/.test(c.id)&&typeof c.name==='string'&&Array.isArray(c.topics)&&c.topics.every(t=>/^[a-z0-9-]+$/.test(t.id)&&typeof t.name==='string'&&Array.isArray(t.lessons)&&t.lessons.every(name=>name===null||typeof name==='string'))))courseCatalog.splice(0,courseCatalog.length,...saved);}
function openTopicForm(button){const courseId=button.dataset.addTopic;showPopup(`<div class="menu-title">Новая тема</div><form id="topic-form" data-course-id="${courseId}"><div class="field"><label for="topic-name">Название темы</label><input id="topic-name" value="Новая тема" maxlength="120" required></div><div class="actions"><button type="button" class="secondary" data-choice="close">Отмена</button><button class="primary" type="submit">Добавить</button></div></form>`,button,320,'topic');$('#topic-name').focus();$('#topic-name').select();}
function addTopic(form){const course=courseCatalog.find(c=>c.id===form.dataset.courseId),name=$('#topic-name').value.trim();if(!course||!name)return;const id='topic-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);course.topics.push({id,name,lessons:[]});hidePopup();renderCourseTree();const courseNode=$('#course-tree').querySelector(`[data-course="${course.id}"]`),topic=courseNode.querySelector(`[data-topic="${id}"]`);courseNode.open=true;topic.open=true;topic.querySelector('summary').focus();saveCatalog().catch(()=>toast('Не удалось сохранить структуру в браузере'));}
function addArticle(button){const course=courseCatalog.find(c=>c.id===button.dataset.addArticle),topic=course?articleContainers(course).find(t=>t.id===button.dataset.topicId):null;if(!topic)return;topic.lessons.push('Новая страница...');renderCourseTree();const courseNode=$('#course-tree').querySelector(`[data-course="${course.id}"]`),topicNode=courseNode.querySelector(`[data-topic="${topic.id}"]`);if(topic.id!=='direct')topicNode.open=true;courseNode.open=true;const links=topicNode.querySelectorAll('.lesson-link');links[links.length-1].focus();saveCatalog().catch(()=>toast('Не удалось сохранить структуру в браузере'));}
$('#course-tree').addEventListener('click',e=>{if(treeSuppressClick){e.preventDefault();e.stopPropagation();treeSuppressClick=false;return;}const sectionDelete=e.target.closest('[data-delete-section]');if(sectionDelete){e.preventDefault();e.stopPropagation();confirmSectionDeletion(sectionDelete);return;}const move=e.target.closest('[data-tree-move]');if(move){e.preventDefault();e.stopPropagation();showTreeMoveMenu(move);return;}const deletion=e.target.closest('[data-delete-topic],[data-delete-article]');if(deletion){e.preventDefault();e.stopPropagation();if(deletion.hasAttribute('data-delete-topic'))confirmTopicDeletion(deletion);else deleteTreeItem('article',deletion.dataset.deleteArticle,deletion.dataset.topicId,Number(deletion.dataset.articleIndex));return;}const topic=e.target.closest('[data-add-topic]');if(topic){openTopicForm(topic);return;}const article=e.target.closest('[data-add-article]');if(article)addArticle(article);});
function syncArticleTitle(snapshot,context){let name=snapshot.title.trim().replace(/^\d+\.\d+\s+/,'');name=name||'Новая страница...';if(context.topic.lessons[context.index]!==name){context.topic.lessons[context.index]=name;context.name=name;if(currentLesson?.id===context.id)renderLessonBreadcrumbs(context);}}

function renderLessonBreadcrumbs(context){const {course,topic,name}=context;$('#lesson-breadcrumbs').innerHTML=`<a href="#courses" aria-label="Все курсы">${img('d707b')}<span>Курсы</span></a><span aria-hidden="true">›</span><a href="#course=${course.id}">${esc(course.name)}</a>${topic.id==='direct'?'':`<span aria-hidden="true">›</span><a href="#course=${course.id}&topic=${topic.id}">${esc(topic.name)}</a>`}<span aria-hidden="true">›</span><span aria-current="page">${esc(name)}</span>`;}
async function persistLesson(snapshot,context){if(!context)return;const workflow=await ensureArticleWorkflow(context,snapshot);recordArticleVersion(workflow,snapshot);syncArticleTitle(snapshot,context);lessonCache.set(context.id,snapshot);if(!db)return Promise.reject(Error('storage unavailable'));return new Promise((resolve,reject)=>{try{const tx=db.transaction('draft','readwrite');tx.objectStore('draft').put(snapshot,'lesson:'+context.id);tx.objectStore('draft').put(workflow,'article-workflow:'+context.id);tx.objectStore('draft').put(courseCatalog,'course-catalog');tx.objectStore('draft').put(syncedBlocks,'synced-blocks');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);}catch(error){reject(error);}});}
function readLesson(context){if(lessonCache.has(context.id))return Promise.resolve(lessonCache.get(context.id));if(!db)return Promise.resolve(null);return new Promise(resolve=>{const tx=db.transaction('draft'),store=tx.objectStore('draft'),request=store.get('lesson:'+context.id);request.onerror=()=>resolve(null);request.onsuccess=()=>{if(request.result||!context.legacy){resolve(request.result||null);return;}const legacy=store.get('current');legacy.onsuccess=()=>resolve(legacy.result||null);legacy.onerror=()=>resolve(null);};});}
async function navigateCourses(){
 if(!loaded||navigationRunning)return;navigationRunning=true;const routeHash=location.hash;$('#catalog').setAttribute('aria-busy','true');
 try{
  clearTimeout(saveTimer);clearTimeout(historyTimer);
  if(currentLesson)await persistLesson(state(),currentLesson).catch(()=>{});
  closeSelection();selectMedia(null);getSelection().removeAllRanges();savedRange=null;currentThread=null;activeBlock=null;
  const params=new URLSearchParams(routeHash.slice(1)),context=lessonContext(params.get('lesson'));
  if(context){
   const draft=await readLesson(context);currentLesson=context;history=[];historyIndex=-1;
   document.body.dataset.view='lesson';$('#catalog').hidden=true;$('#lesson-page').hidden=false;
   renderLessonBreadcrumbs(context);$('#save-status').textContent='';
   const initial=draft||{html:'<p><br></p>',title:context.name==='Новая страница...'?'':context.name,comments:{}};await ensureArticleWorkflow(context,initial);renderArticleStatus();applyState(initial);pushHistory();
   $('#lesson-page').focus({preventScroll:true});
  }else{
   currentLesson=null;renderCourseTree();document.body.dataset.view='catalog';$('#catalog').hidden=false;$('#lesson-page').hidden=true;
   const courseId=params.get('course'),topicId=params.get('topic');
   if(courseId){for(const course of $('#course-tree').querySelectorAll('.course-node'))course.open=course.dataset.course===courseId;
    const course=$('#course-tree').querySelector(`[data-course="${courseId.replace(/[^a-z0-9-]/g,'')}"]`);
    if(course&&topicId)for(const topic of course.querySelectorAll('.topic-node'))topic.open=topic.dataset.topic===topicId;
   }
   $('#catalog-heading').focus({preventScroll:true});
  }
  window.scrollTo(0,0);
 }finally{navigationRunning=false;$('#catalog').removeAttribute('aria-busy');if(location.hash!==routeHash)await navigateCourses();}
}
window.addEventListener('hashchange',navigateCourses);

function treeDeleteButton(kind,course,topic,index=''){return `<button class="tree-delete" type="button" data-delete-${kind}="${course.id}" data-topic-id="${topic.id}"${kind==='article'?` data-article-index="${index}"`:''} aria-label="Удалить ${kind==='topic'?'тему':'статью'}: ${esc(kind==='topic'?topic.name:topic.lessons[index])}" title="Удалить ${kind==='topic'?'тему':'статью'}"><img src="assets/trash.svg" width="20" height="20" alt=""></button>`;}
function confirmTopicDeletion(button){const course=courseCatalog.find(c=>c.id===button.dataset.deleteTopic),topic=course?articleContainers(course).find(t=>t.id===button.dataset.topicId):null;if(!topic)return;const count=topic.lessons.filter(n=>n!==null).length;showPopup(`<form id="delete-topic-form" data-course-id="${course.id}" data-topic-id="${topic.id}"><div class="field"><h2 class="delete-topic-title">Удалить тему?</h2><p class="delete-topic-warning">Тема «${esc(topic.name)}» и все статьи внутри будут удалены${count?' — '+countLabel(count,['статья','статьи','статей']):''}. Это действие нельзя отменить.</p></div><div class="actions"><button class="secondary" type="button" data-choice="close">Отмена</button><button class="primary" type="submit">Удалить тему</button></div></form>`,button,360,'delete-topic');popup.setAttribute('role','dialog');popup.setAttribute('aria-label','Удаление темы');popup.querySelector('[data-choice="close"]').focus();}
async function deleteTreeItem(kind,courseId,topicId,index){const next=structuredClone(courseCatalog),course=next.find(c=>c.id===courseId),topic=course?articleContainers(course).find(t=>t.id===topicId):null;if(!topic)return;const ids=[];if(kind==='topic'){topic.lessons.forEach((name,i)=>{if(name!==null)ids.push(topic.lessonIds[i]);});course.topics=course.topics.filter(t=>t.id!==topicId);}else{if(!Number.isInteger(index)||topic.lessons[index]==null)return;topic.lessons[index]=null;ids.push(topic.lessonIds[index]);}const submit=$('#delete-topic-form button[type="submit"]');if(submit)submit.disabled=true;try{if(!db)throw Error('storage');await new Promise((resolve,reject)=>{const tx=db.transaction('draft','readwrite'),store=tx.objectStore('draft');ids.forEach(id=>{store.delete('lesson:'+id);store.delete('article-workflow:'+id);});store.put(next,'course-catalog');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});courseCatalog.splice(0,courseCatalog.length,...next);ids.forEach(id=>{lessonCache.delete(id);articleWorkflows.delete(id);});hidePopup();renderCourseTree();const node=$('#course-tree').querySelector(`[data-course="${courseId}"]`);node?.querySelector('summary').focus();toast(kind==='topic'?'Тема удалена':'Статья удалена');}catch{if(submit)submit.disabled=false;toast('Не удалось удалить. Попробуйте ещё раз.');}}

function ensureArticleIds(){const reserved=new Set(),seen=new Set();for(const course of courseCatalog)for(const topic of articleContainers(course))topic.lessonIds?.forEach((id,i)=>{if(topic.lessons[i]!==null&&/^[a-z0-9-]+$/.test(id))reserved.add(id);});for(const course of courseCatalog)for(const topic of articleContainers(course)){topic.lessonIds=Array.isArray(topic.lessonIds)?topic.lessonIds:[];topic.lessons.forEach((name,i)=>{if(typeof name==='string')topic.lessons[i]=name.replace(/^\d+\.\d+(?:\.\d+)*\s+/,'');let id=topic.lessonIds[i];const existing=!!id&&/^[a-z0-9-]+$/.test(id);if(!existing){id=`${course.id}-${topic.id}-${i+1}`;if(name!==null&&reserved.has(id))id='article-'+crypto.randomUUID();}if(name!==null&&seen.has(id))id='article-'+crypto.randomUUID();topic.lessonIds[i]=id;if(name!==null){reserved.add(id);seen.add(id);}});}}

function locateArticle(id,catalog=courseCatalog){for(const course of catalog)for(const topic of articleContainers(course)){const index=topic.lessonIds?.findIndex((key,i)=>key===id&&topic.lessons[i]!==null);if(index>=0)return{course,topic,index,id};}return null;}
function treeMoveHandle(kind,id){return `<button class="tree-handle" draggable="false" type="button" data-tree-move="${kind}" data-move-id="${id}" aria-label="Переместить ${kind==='topic'?'тему':'статью'}" title="Перетащите или нажмите для перемещения"><span class="drag-dots" aria-hidden="true"></span></button>`;}
async function commitTreeMove(next,focusId){try{if(!db)throw Error('storage');await new Promise((resolve,reject)=>{const tx=db.transaction('draft','readwrite');tx.objectStore('draft').put(next,'course-catalog');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});courseCatalog.splice(0,courseCatalog.length,...next);hidePopup();renderCourseTree();if(focusId){const link=$('#course-tree').querySelector(`[data-article-id="${focusId}"] .lesson-link`);if(link){link.closest('.course-node').open=true;link.closest('.topic-node')?.setAttribute('open','');link.focus();}else $('#course-tree').querySelector(`[data-topic="${focusId}"]>summary`)?.focus();}toast('Порядок и расположение сохранены');}catch{toast('Не удалось переместить. Попробуйте ещё раз.');}}
async function moveArticle(id,courseId,topicId,beforeId=null){const next=structuredClone(courseCatalog),source=locateArticle(id,next),target=(()=>{const c=next.find(c=>c.id===courseId);return c?articleContainers(c).find(t=>t.id===topicId):null;})();if(!source||!target||beforeId===id)return;const [name]=source.topic.lessons.splice(source.index,1);source.topic.lessonIds.splice(source.index,1);let index=beforeId?target.lessonIds.indexOf(beforeId):-1;if(index<0)index=target.lessons.length;target.lessons.splice(index,0,name);target.lessonIds.splice(index,0,id);await commitTreeMove(next,id);}
async function moveTopic(id,courseId,beforeId=null){if(id===beforeId)return;const next=structuredClone(courseCatalog),course=next.find(c=>c.id===courseId),index=course?.topics.findIndex(t=>t.id===id);if(index==null||index<0)return;const [topic]=course.topics.splice(index,1);let targetIndex=beforeId?course.topics.findIndex(t=>t.id===beforeId):-1;if(targetIndex<0)targetIndex=course.topics.length;course.topics.splice(targetIndex,0,topic);await commitTreeMove(next,id);}
function showTreeMoveMenu(handle){const kind=handle.dataset.treeMove,id=handle.dataset.moveId,source=kind==='article'?locateArticle(id):null,course=kind==='topic'?courseCatalog.find(c=>c.topics.some(t=>t.id===id)):source?.course;if(!course)return;const items=kind==='topic'?course.topics.map(t=>t.id):source.topic.lessonIds.filter((key,i)=>source.topic.lessons[i]!==null),index=items.indexOf(id);showPopup(`<div class="menu-title">${kind==='topic'?'Порядок темы':'Переместить статью'}</div><button class="menu-item" data-tree-order="up" ${index===0?'disabled':''}>↑ Выше</button><button class="menu-item" data-tree-order="down" ${index===items.length-1?'disabled':''}>↓ Ниже</button>${kind==='article'?`<form id="move-article-form"><div class="field"><label for="move-article-target">Куда переместить</label><select id="move-article-target">${courseCatalog.map(c=>`<optgroup label="${esc(c.name)}">${articleContainers(c).map(t=>`<option value="${c.id}:${t.id}"${t.id===source.topic.id&&c.id===source.course.id?' selected':''}>${t.id==='direct'?'В раздел без темы':esc(t.name)}</option>`).join('')}</optgroup>`).join('')}</select></div><div class="actions"><button class="secondary" type="button" data-choice="close">Отмена</button><button class="primary" type="submit">Переместить</button></div></form>`:''}`,handle,320,'tree-move');popup.movingItem={kind,id,courseId:course.id};}
function orderTreeItem(direction){const item=popup.movingItem;if(!item)return;const source=item.kind==='article'?locateArticle(item.id):null,course=courseCatalog.find(c=>c.id===item.courseId),ids=item.kind==='topic'?course.topics.map(t=>t.id):source.topic.lessonIds.filter((id,i)=>source.topic.lessons[i]!==null),index=ids.indexOf(item.id);if(direction==='up'&&index>0){if(item.kind==='topic')moveTopic(item.id,course.id,ids[index-1]);else moveArticle(item.id,source.course.id,source.topic.id,ids[index-1]);}else if(direction==='down'&&index<ids.length-1){if(item.kind==='topic')moveTopic(item.id,course.id,ids[index+2]||null);else moveArticle(item.id,source.course.id,source.topic.id,ids[index+2]||null);}}
popup.addEventListener('click',e=>{const button=e.target.closest('[data-tree-order]');if(button)orderTreeItem(button.dataset.treeOrder);});
let treeDrag=null,treeDrop=null,treeExpandTimer;
function clearTreeDrop(){document.querySelectorAll('.tree-drop-before,.tree-drop-after,.tree-drop-topic').forEach(n=>n.classList.remove('tree-drop-before','tree-drop-after','tree-drop-topic'));}
function finishTreeDrag(){treeDrag=null;treeDrop=null;clearTimeout(treeExpandTimer);clearTreeDrop();document.querySelectorAll('.tree-dragging').forEach(n=>n.classList.remove('tree-dragging'));}
$('#course-tree').addEventListener('dragstart',e=>{const handle=e.target.closest('[data-tree-move]');if(!handle){e.preventDefault();return;}hidePopup();treeDrag={kind:handle.dataset.treeMove,id:handle.dataset.moveId,courseId:handle.closest('.course-node').dataset.course};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',treeDrag.id);handle.closest(treeDrag.kind==='topic'?'.topic-node':'.lesson-row').classList.add('tree-dragging');});
function updateTreeDrop(e){if(!treeDrag)return;const course=e.target?.closest('.course-node'),topic=e.target?.closest('.topic-node,.section-articles')||(treeDrag.kind==='article'?course?.querySelector('.section-articles'):null);if(!topic||!course)return;clearTreeDrop();treeDrop=null;if(treeDrag.kind==='topic'){if(!topic.classList.contains('topic-node')||course.dataset.course!==treeDrag.courseId||topic.dataset.topic===treeDrag.id)return;e.preventDefault();const rect=topic.getBoundingClientRect(),after=e.clientY>rect.top+rect.height/2;topic.classList.add(after?'tree-drop-after':'tree-drop-before');treeDrop={courseId:course.dataset.course,beforeId:after?(topic.nextElementSibling?.dataset.topic||null):topic.dataset.topic};}else{e.preventDefault();const row=e.target.closest('.lesson-row');if(row){const rect=row.getBoundingClientRect(),after=e.clientY>rect.top+rect.height/2;row.classList.add(after?'tree-drop-after':'tree-drop-before');treeDrop={courseId:course.dataset.course,topicId:topic.dataset.topic,beforeId:after?(row.nextElementSibling?.dataset.articleId||null):row.dataset.articleId};}else{topic.classList.add('tree-drop-topic');treeDrop={courseId:course.dataset.course,topicId:topic.dataset.topic,beforeId:null};if(topic.classList.contains('topic-node')&&!topic.open&&!treeExpandTimer)treeExpandTimer=setTimeout(()=>{topic.open=true;treeExpandTimer=null;},600);}}if(e.clientY>innerHeight-60)window.scrollBy(0,16);else if(e.clientY<130)window.scrollBy(0,-16);e.dataTransfer.dropEffect='move';}
$('#course-tree').addEventListener('dragover',updateTreeDrop);
$('#course-tree').addEventListener('drop',e=>{if(!treeDrag||!treeDrop)return;e.preventDefault();const source=treeDrag,target=treeDrop;finishTreeDrag();if(source.kind==='topic')moveTopic(source.id,target.courseId,target.beforeId);else moveArticle(source.id,target.courseId,target.topicId,target.beforeId);});
$('#course-tree').addEventListener('dragend',finishTreeDrag);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&treeDrag)finishTreeDrag();});


let treePointer=null,treeSuppressClick=false;
$('#course-tree').addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-tree-move]');if(!handle||e.button!==0)return;e.preventDefault();e.stopPropagation();treePointer={handle,x:e.clientX,y:e.clientY,started:false};handle.setPointerCapture(e.pointerId);});
$('#course-tree').addEventListener('pointermove',e=>{if(!treePointer)return;const p=treePointer;if(!p.started&&Math.hypot(e.clientX-p.x,e.clientY-p.y)>5){p.started=true;hidePopup();treeDrag={kind:p.handle.dataset.treeMove,id:p.handle.dataset.moveId,courseId:p.handle.closest('.course-node').dataset.course};p.handle.closest(treeDrag.kind==='topic'?'.topic-node':'.lesson-row').classList.add('tree-dragging');}if(p.started)updateTreeDrop({target:document.elementFromPoint(e.clientX,e.clientY),clientX:e.clientX,clientY:e.clientY,preventDefault(){},dataTransfer:{}});});
