$('#course-tree').addEventListener('pointercancel',()=>{treePointer=null;finishTreeDrag();});

let syncedBlocks={},syncedClipboard=null,syncedMutationSource=null;
const syncTokenPrefix='cu-synced-block:';
function syncedContentRecord(block){const content=block.querySelector(':scope>.synced-content'),copy=content.cloneNode(true);copy.querySelectorAll('.selected,.drag-source,.anchor-flash').forEach(n=>n.classList.remove('selected','drag-source','anchor-flash'));const threadIds=new Set([...copy.querySelectorAll('[data-comment-id]')].map(n=>n.dataset.commentId));return{html:copy.innerHTML,comments:Object.fromEntries([...threadIds].filter(id=>comments[id]).map(id=>[id,structuredClone(comments[id])]))};}
function syncedHeadingHTML(){return `<span>${img('synced')}Синхронизируемый блок</span><div class="synced-actions"><button type="button" data-sync-action="usage" aria-label="Где используется блок" title="Где используется блок">${img('block-usage')}</button><button type="button" data-sync-action="copy" aria-label="Копировать синхронизируемый блок" title="Копировать синхронизируемый блок">${img('copy-block')}</button><button type="button" data-sync-action="detach" aria-label="Отключить синхронизацию этого блока" title="Отключить синхронизацию этого блока">${img('unlink-block')}</button><button type="button" data-sync-action="delete" aria-label="Удалить этот экземпляр блока" title="Удалить этот экземпляр блока">${img('trash')}</button></div>`;}
function syncedBlockHTML(id){const record=syncedBlocks[id];return `<section class="block synced-block" contenteditable="false" data-synced-id="${id}"><div class="synced-heading">${syncedHeadingHTML()}</div><div class="synced-content" contenteditable="true" role="textbox" aria-label="Содержимое синхронизируемого блока">${record.html}</div></section>`;}
function hydrateSyncedBlocks(fromHistory=false){const blocks=[...editor.querySelectorAll('.synced-block')];for(const block of blocks){const id=block.dataset.syncedId;if(!/^s[a-z0-9-]+$/.test(id)||!block.querySelector(':scope>.synced-content')){block.remove();continue;}if(!syncedBlocks[id]||fromHistory)syncedBlocks[id]={...syncedContentRecord(block),updatedAt:Date.now()};const heading=block.querySelector(':scope>.synced-heading');if(heading)heading.innerHTML=syncedHeadingHTML();const record=syncedBlocks[id];Object.assign(comments,structuredClone(record.comments||{}));block.querySelector(':scope>.synced-content').innerHTML=record.html;}}
function syncSharedBlocks(){const changedIds=[];const groups=new Map();for(const block of editor.querySelectorAll('.synced-block')){const id=block.dataset.syncedId;if(!block.querySelector(':scope>.synced-content'))continue;if(!groups.has(id))groups.set(id,[]);groups.get(id).push(block);}const selected=parentElement(getSelection().anchorNode)?.closest('.synced-block');for(const[id,blocks]of groups){const record=syncedBlocks[id],diff=block=>{const next=syncedContentRecord(block);return !record||next.html!==record.html||JSON.stringify(next.comments)!==JSON.stringify(record.comments||{});};const source=syncedMutationSource?.isConnected&&blocks.includes(syncedMutationSource)?syncedMutationSource:selected&&blocks.includes(selected)?selected:blocks.find(diff)||blocks[0],next=syncedContentRecord(source);if(!record||next.html!==record.html||JSON.stringify(next.comments)!==JSON.stringify(record.comments||{})){syncedBlocks[id]={...next,updatedAt:Date.now()};changedIds.push(id);}for(const block of blocks)if(block!==source&&block.querySelector(':scope>.synced-content').innerHTML!==next.html)block.querySelector(':scope>.synced-content').innerHTML=next.html;}if(changedIds.length)broadcastSyncedBlocks(changedIds);}
async function loadSyncedBlocks(){if(!db)return;await new Promise(resolve=>{const tx=db.transaction('draft'),store=tx.objectStore('draft'),req=store.get('synced-blocks');req.onsuccess=()=>{if(req.result&&typeof req.result==='object')syncedBlocks=req.result;};const clip=store.get('synced-clipboard');clip.onsuccess=()=>syncedClipboard=clip.result||null;tx.oncomplete=resolve;tx.onerror=resolve;});}
function chooseSyncedBlock(anchor){let rect=anchor instanceof Element?anchor.getBoundingClientRect():anchor;if(!rect?.width)rect=$('#toolbar [data-action="synced"]').getBoundingClientRect();const entries=Object.entries(syncedBlocks);showPopup('<div class="menu-title">Синхронизируемые блоки</div><button class="menu-item" data-sync-create>Сделать текущий блок общим</button><button class="menu-item" data-sync-empty>Создать пустой блок</button>'+ (syncedClipboard&&syncedBlocks[syncedClipboard]?`<button class="menu-item" data-sync-insert="${syncedClipboard}">${img('copy-block')}Вставить скопированный блок</button>`:'')+(entries.length?'<div class="menu-title">Вставить существующий</div>'+entries.map(([id,record])=>{const t=document.createElement('template');t.innerHTML=record.html;const label=t.content.textContent.trim().replace(/\s+/g,' ').slice(0,65)||'Пустой блок';return `<button class="menu-item" data-sync-insert="${id}">${img('synced')}<span>${esc(label)}</span></button>`;}).join(''):''),rect,330,'synced');}
function createSyncedBlock(empty=false){remember();const selectionBlock=topBlock(savedRange?.startContainer),target=selectionBlock||activeBlock;if(target?.matches('.synced-block')||target?.querySelector('.synced-block')){toast('Этот блок уже синхронизируется');return;}const id='s'+crypto.randomUUID(),html=empty||!target?'<p><br></p>':target.outerHTML;pushHistory();syncedBlocks[id]={html,comments:structuredClone(comments),updatedAt:Date.now()};if(empty||!target){insertSyncedBlock(id);}else{const template=document.createElement('template');template.innerHTML=syncedBlockHTML(id);const block=template.content.firstElementChild;target.replaceWith(block);if(!block.nextSibling)block.after(document.createElement('p'));hidePopup();caret(block.querySelector('.synced-content'),true);changed();}}
function insertSyncedBlock(id){if(!syncedBlocks[id]){toast('Синхронизируемый блок не найден');return;}const selected=parentElement(savedRange?.startContainer)?.closest('.synced-block');if(selected){toast('Поставьте курсор вне синхронизируемого блока');return;}Object.assign(comments,structuredClone(syncedBlocks[id].comments||{}));insertBlock(syncedBlockHTML(id));}
function copySyncedBlock(block){const id=block.dataset.syncedId;syncedClipboard=id;syncSharedBlocks();broadcastSyncedBlocks([id]);if(db){const tx=db.transaction('draft','readwrite');tx.objectStore('draft').put(id,'synced-clipboard');}navigator.clipboard?.writeText(syncTokenPrefix+id).catch(()=>{});toast('Блок скопирован. В другой статье выберите «Вставить скопированный блок» или нажмите Cmd/Ctrl + V.');}
function handleSyncedAction(button){const block=button.closest('.synced-block');if(!block)return;if(button.dataset.syncAction==='copy'){copySyncedBlock(block);return;}if(button.dataset.syncAction==='usage'){showSyncedUsage(block,button);return;}pushHistory();if(button.dataset.syncAction==='detach'){const content=block.querySelector(':scope>.synced-content'),fragment=document.createDocumentFragment();let paragraph=null;for(const node of [...content.childNodes]){if(node.nodeType===1&&node.matches('p,div,h1,h2,h3,h4,h5,h6,ul,ol,blockquote,pre,table,hr,figure,aside,details,section')){paragraph=null;fragment.append(node);}else{if(!paragraph){paragraph=document.createElement('p');fragment.append(paragraph);}paragraph.append(node);}}const nodes=[...fragment.childNodes];block.replaceWith(fragment);savedRange=null;if(nodes[0])caret(nodes[0]);toast('Этот экземпляр больше не синхронизируется');}else{block.remove();savedRange=null;toast('Экземпляр удалён. Другие экземпляры сохранены');}changed();}


const syncedChannel=typeof BroadcastChannel==='function'?new BroadcastChannel('cu-longread-synced'):null;
function broadcastSyncedBlocks(ids){syncedChannel?.postMessage({blocks:Object.fromEntries(ids.filter(id=>syncedBlocks[id]).map(id=>[id,syncedBlocks[id]]))});}
if(syncedChannel)syncedChannel.onmessage=e=>{let updated=false;for(const[id,record]of Object.entries(e.data?.blocks||{})){if(!/^s[a-z0-9-]+$/.test(id)||typeof record.html!=='string')continue;if(!syncedBlocks[id]||record.updatedAt>=syncedBlocks[id].updatedAt){syncedBlocks[id]=record;updated=true;}}if(updated&&currentLesson){hydrateSyncedBlocks();updateEmpty();save();}};
editor.addEventListener('input',e=>{syncedMutationSource=e.target.closest('.synced-block');},true);
document.addEventListener('pointerdown',e=>{const block=e.target.closest('.synced-block');if(block)syncedMutationSource=block;else if(e.target.closest('#toolbar,#bubble'))syncedMutationSource=parentElement(savedRange?.startContainer)?.closest('.synced-block')||null;},true);

function renameRootSections(){const names={backend:'Кампус',math:'Учебный процесс',design:'Другое'};const descriptions={backend:'Адреса корпусов, пространства и сервисы кампуса',math:'Организация обучения, правила и учебные материалы',design:'Полезные контакты, ответы на вопросы и дополнительные материалы'};for(const section of courseCatalog)if(names[section.id]){section.name=names[section.id];section.description=descriptions[section.id];}}

async function updateCampusTopics(){
 const migrationKey='campus-topics-v1';
 if(db){const done=await new Promise(resolve=>{const req=db.transaction('draft').objectStore('draft').get(migrationKey);req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(false);});if(done)return;}
 const next=structuredClone(courseCatalog),campus=next.find(c=>c.id==='backend');if(!campus)return;
 if(campus.topics[0])campus.topics[0].name='Центральный Телеграф';if(campus.topics[1])campus.topics[1].name='Дукат';
 const removed=campus.topics.splice(2,1)[0];
 if(db)await new Promise((resolve,reject)=>{const tx=db.transaction('draft','readwrite'),store=tx.objectStore('draft');
  if(removed){store.put(removed,'campus-removed-topic-backup');removed.lessons.forEach((name,i)=>{if(name===null)return;const id=removed.lessonIds?.[i]||`backend-${removed.id}-${i+1}`;const req=store.get('lesson:'+id);req.onsuccess=()=>{if(req.result)store.put(req.result,'campus-backup:'+id);store.delete('lesson:'+id);};});}
  store.put(next,'course-catalog');store.put(true,migrationKey);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);
 });
 courseCatalog.splice(0,courseCatalog.length,...next);
}

async function updateStudyTopics(){
 const key='study-topics-v1';
 if(db){const done=await new Promise(resolve=>{const req=db.transaction('draft').objectStore('draft').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(false);});if(done)return;}
 const next=structuredClone(courseCatalog),section=next.find(c=>c.id==='math');if(!section)return;
 ['Расписание','Перезачёты','Справки','Правила обучения'].forEach((name,i)=>{if(section.topics[i])section.topics[i].name=name;else section.topics.push({id:'study-topic-'+(i+1),name,lessons:[],lessonIds:[]});});
 if(db)await new Promise((resolve,reject)=>{const tx=db.transaction('draft','readwrite'),store=tx.objectStore('draft');store.put(next,'course-catalog');store.put(true,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});
 courseCatalog.splice(0,courseCatalog.length,...next);
}


$('#add-section').addEventListener('click',()=>{showPopup('<div class="menu-title">Новый раздел</div><form id="section-form"><div class="field"><label for="section-name">Название раздела</label><input id="section-name" maxlength="120" placeholder="Новый раздел" required></div><div class="field"><label for="section-description">Описание (необязательно)</label><input id="section-description" maxlength="200" placeholder="О чём этот раздел"></div><div class="actions"><button type="button" class="secondary" data-choice="close">Отмена</button><button class="primary" type="submit">Добавить</button></div></form>',$('#add-section'),360,'section');popup.setAttribute('role','dialog');popup.setAttribute('aria-label','Новый раздел');$('#section-name').focus();});
async function addSection(form){const input=$('#section-name'),name=input.value.trim();if(!name){input.value='';input.reportValidity();return;}const id='section-'+crypto.randomUUID(),section={id,name,description:$('#section-description').value.trim(),topics:[]},next=structuredClone(courseCatalog);next.push(section);const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{if(!db)throw Error('storage');await new Promise((resolve,reject)=>{const tx=db.transaction('draft','readwrite');tx.objectStore('draft').put(next,'course-catalog');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});courseCatalog.splice(0,courseCatalog.length,...next);hidePopup();renderCourseTree();const node=$('#course-tree').querySelector(`[data-course="${id}"]`);node.open=true;node.querySelector('summary').focus();node.scrollIntoView({block:'nearest'});}catch{submit.disabled=false;toast('Не удалось создать раздел. Попробуйте ещё раз.');}}

function sectionDeleteButton(section){return `<button class="tree-delete" type="button" data-delete-section="${section.id}" aria-label="Удалить раздел: ${esc(section.name)}" title="Удалить раздел"><img src="assets/trash.svg" width="20" height="20" alt=""></button>`;}
function confirmSectionDeletion(button){const section=courseCatalog.find(c=>c.id===button.dataset.deleteSection);if(!section)return;const count=articleContainers(section).reduce((sum,t)=>sum+t.lessons.filter(n=>n!==null).length,0);showPopup(`<form id="delete-section-form" data-section-id="${section.id}"><div class="field"><h2 class="delete-topic-title">Удалить раздел?</h2><p class="delete-topic-warning">Раздел «${esc(section.name)}» и все темы и статьи внутри будут удалены: ${countLabel(section.topics.length,['тема','темы','тем'])}, ${countLabel(count,['статья','статьи','статей'])}. Это действие нельзя отменить.</p></div><div class="actions"><button type="button" class="secondary" data-choice="close">Отмена</button><button class="primary" type="submit">Удалить раздел</button></div></form>`,button,380,'delete-section');popup.setAttribute('role','dialog');popup.setAttribute('aria-label','Удаление раздела');popup.querySelector('[data-choice="close"]').focus();}
async function deleteSection(form){const id=form.dataset.sectionId,section=courseCatalog.find(c=>c.id===id);if(!section)return;const next=structuredClone(courseCatalog.filter(c=>c.id!==id)),ids=articleContainers(section).flatMap(t=>t.lessons.flatMap((name,i)=>name===null?[]:[t.lessonIds[i]])),submit=form.querySelector('[type="submit"]');submit.disabled=true;try{if(!db)throw Error('storage');await new Promise((resolve,reject)=>{const tx=db.transaction('draft','readwrite'),store=tx.objectStore('draft');ids.forEach(key=>{store.delete('lesson:'+key);store.delete('article-workflow:'+key);});store.put(next,'course-catalog');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});courseCatalog.splice(0,courseCatalog.length,...next);ids.forEach(key=>{lessonCache.delete(key);articleWorkflows.delete(key);});hidePopup();renderCourseTree();$('#catalog-heading').focus({preventScroll:true});toast('Раздел удалён');}catch{submit.disabled=false;toast('Не удалось удалить раздел. Попробуйте ещё раз.');}}

function articleContainers(course){if(!course.directArticles)course.directArticles={id:'direct',name:course.name,lessons:[],lessonIds:[]};return[course.directArticles,...course.topics];}
function renderArticleRows(course,container){return container.lessons.map((name,index)=>name===null?'':`<div class="lesson-row" data-article-id="${container.lessonIds[index]}">${treeMoveHandle('article',container.lessonIds[index])}<a class="lesson-link" href="#lesson=${container.lessonIds[index]}"><span>${esc(name)}</span><span class="lesson-open" aria-hidden="true">→</span></a>${treeDeleteButton('article',course,container,index)}</div>`).join('');}

