async function showSyncedUsage(block,button){
 const id=block.dataset.syncedId,anchor=button.getBoundingClientRect();
 showPopup('<div class="menu-title">Где используется блок</div><p class="sync-usage-status" role="status">Ищем статьи…</p>',anchor,380,'synced-usage');
 const request=Symbol();popup.usageRequest=request;
 try{
  const drafts=await new Promise((resolve,reject)=>{
   if(!db){reject(Error('storage'));return;}
   const tx=db.transaction('draft'),store=tx.objectStore('draft'),result=new Map();
   for(const course of courseCatalog)for(const topic of articleContainers(course))topic.lessons.forEach((name,i)=>{
    if(name===null)return;const articleId=topic.lessonIds[i],req=store.get('lesson:'+articleId);
    req.onsuccess=()=>result.set(articleId,req.result);
   });
   const legacy=store.get('current');legacy.onsuccess=()=>result.set('legacy',legacy.result);
   tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);
  });
  if(popup.hidden||menuKind!=='synced-usage'||popup.usageRequest!==request)return;
  const articles=[];
  for(const course of courseCatalog)for(const topic of articleContainers(course))topic.lessons.forEach((name,i)=>{
   if(name===null)return;const articleId=topic.lessonIds[i],current=articleId===currentLesson?.id;
   const draft=current?state():drafts.get(articleId)||(articleId==='backend-web-2'?drafts.get('legacy'):null);
   if(!draft?.html)return;const template=document.createElement('template');template.innerHTML=draft.html;
   if(![...template.content.querySelectorAll('.synced-block')].some(n=>n.dataset.syncedId===id))return;
   articles.push({id:articleId,name:draft.title?.trim()||name,path:course.name+(topic.id==='direct'?'':' / '+topic.name),current});
  });
  showPopup('<div class="sync-usage-heading"><strong>Где используется блок</strong><button type="button" data-choice="close" aria-label="Закрыть">×</button></div><p class="sync-usage-status">'+countLabel(articles.length,['статья','статьи','статей'])+'</p><div class="sync-usage-list">'+articles.map(a=>`<a class="sync-usage-link" href="#lesson=${a.id}" data-sync-usage-link><span>${esc(a.name)}</span><small>${esc(a.path)}${a.current?' · Текущая статья':''}</small></a>`).join('')+'</div>',anchor,380,'synced-usage');
  popup.setAttribute('role','dialog');popup.setAttribute('aria-label','Где используется блок');
 }catch{if(!popup.hidden&&menuKind==='synced-usage'&&popup.usageRequest===request)showPopup('<div class="menu-title">Где используется блок</div><p class="sync-usage-status">Не удалось загрузить список статей. Закройте меню и попробуйте еще раз.</p>',anchor,380,'synced-usage');}
}
document.addEventListener('click',e=>{if(e.target.closest('[data-sync-usage-link]'))hidePopup();});

const articleWorkflows=new Map(),workflowLoads=new Map();
async function ensureArticleWorkflow(context,snapshot){
 if(articleWorkflows.has(context.id))return articleWorkflows.get(context.id);
 if(workflowLoads.has(context.id))return workflowLoads.get(context.id);
 const pending=(async()=>{
  const saved=db?await new Promise(resolve=>{const req=db.transaction('draft').objectStore('draft').get('article-workflow:'+context.id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);}):null;
  const data=saved||{published:false,versions:[
   {at:'2026-10-19T09:30:00+03:00',author:'Анна Смирнова',demo:true,snapshot:structuredClone(snapshot)},
   {at:'2026-10-20T14:15:00+03:00',author:'Иван Петров',demo:true,snapshot:structuredClone(snapshot)},
   {at:'2026-10-21T11:45:00+03:00',author:'editor.cu',demo:true,snapshot:structuredClone(snapshot)}]};
  articleWorkflows.set(context.id,data);workflowLoads.delete(context.id);return data;
 })();workflowLoads.set(context.id,pending);return pending;
}
function recordArticleVersion(workflow,snapshot){
 if(JSON.stringify(workflow.versions.at(-1)?.snapshot)===JSON.stringify(snapshot))return;
 workflow.versions.push({at:new Date().toISOString(),author:currentUser.login,snapshot:structuredClone(snapshot)});
}
function renderArticleStatus(){const published=articleWorkflows.get(currentLesson?.id)?.published;const badge=$('#article-status');badge.textContent=published?'Опубликована':'Черновик';badge.dataset.published=String(!!published);}
function showArticleMenu(){if(!currentLesson)return;const rect=$('#more').getBoundingClientRect();const published=articleWorkflows.get(currentLesson.id)?.published;showPopup(`<button class="menu-item" data-article-action="publish">${published?'Снять с публикации':'Опубликовать'}</button><button class="menu-item" data-article-action="preview">Предварительный просмотр</button><button class="menu-item" data-article-action="history">История изменений</button><button class="menu-item" type="button">Кто может просматривать</button>`,{left:rect.right-280,bottom:rect.bottom},280,'settings');}
async function publishArticle(){
 if(!currentLesson)return;const context=currentLesson,workflow=await ensureArticleWorkflow(context,state()),previous=workflow.published;
 workflow.published=!previous;
 try{clearTimeout(saveTimer);await persistLesson(state(),context);renderArticleStatus();hidePopup();toast(workflow.published?'Статья опубликована':'Статья снята с публикации');}catch{workflow.published=previous;renderArticleStatus();toast('Не удалось сохранить статус статьи');}
}
function versionDate(value){return new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Moscow'}).format(new Date(value)).replace(',','');}
function readOnlyArticle(snapshot){
 const content=document.createElement('div');content.id='reader-content';content.innerHTML=snapshot.html;
 content.querySelectorAll('.synced-heading,.block-controls,.accordion-actions,.image-align-toolbar,.image-controls,.resize-handle,[data-block-action],[data-accordion-action],[data-restore-caption]').forEach(n=>n.remove());
 content.querySelectorAll('[contenteditable]').forEach(n=>{n.setAttribute('contenteditable','false');if(n.getAttribute('role')==='textbox')n.removeAttribute('role');n.removeAttribute('aria-multiline');});
 content.querySelectorAll('button.info-emoji').forEach(button=>{const icon=document.createElement('span');icon.className='info-emoji';icon.textContent=button.textContent;button.replaceWith(icon);});
 content.querySelectorAll('button,input,textarea,select').forEach(n=>{n.disabled=true;});
 content.querySelectorAll('[draggable]').forEach(n=>n.setAttribute('draggable','false'));
 const heading=document.createElement('h1');heading.textContent=snapshot.title.trim()||'Новая страница...';
 const article=document.createElement('article');article.className='reader-article';article.append(heading,content);return article;
}
async function openArticleReader(mode){
 if(!currentLesson)return;clearTimeout(saveTimer);const context=currentLesson,snapshot=state();
 try{await persistLesson(snapshot,context);}catch{toast('Не удалось сохранить изменения');return;}
 if(currentLesson?.id!==context.id)return;hidePopup();closeSelection();
 const workflow=articleWorkflows.get(context.id),overlay=$('#article-reader');overlay.classList.toggle('history-drawer-mode',mode==='history');
 if(mode==='history'){
  overlay.innerHTML='<div class="reader-backdrop" data-reader-close></div><div id="reader-page" hidden></div><aside class="history-drawer"><div class="reader-top"><strong>История изменений</strong><button type="button" data-reader-close aria-label="Закрыть историю изменений">×</button></div><div class="reader-history"><p>Пример истории</p><small>Первые три записи — демонстрационные. Новые изменения сохраняются автоматически.</small><div id="version-list"></div></div></aside>';
  const list=$('#version-list');workflow.versions.forEach((version,i)=>{const button=document.createElement('button');button.type='button';button.dataset.version=i;button.textContent=versionDate(version.at)+' — '+version.author;button.setAttribute('aria-pressed','false');list.prepend(button);});
 }else{
  overlay.innerHTML='<div class="reader-top"><strong>Предварительный просмотр</strong><button type="button" data-reader-close>Вернуться к редактированию</button></div><div class="reader-layout"><div id="reader-page"></div></div>';
  $('#reader-page').append(readOnlyArticle(snapshot));
 }
 overlay.hidden=false;overlay.setAttribute('aria-label',mode==='history'?'История изменений':'Предварительный просмотр');document.body.classList.add('reader-open');$('#lesson-page').inert=true;$('#toolbar').inert=true;overlay.querySelector('button[data-reader-close]').focus();
}

function showArticleVersion(index){const workflow=articleWorkflows.get(currentLesson?.id),version=workflow?.versions[index];if(!version)return;$('#reader-page').hidden=false;$('#reader-page').replaceChildren(readOnlyArticle(version.snapshot));$('#version-list').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.version)===index)));$('#reader-page').scrollTop=0;}
function closeArticleReader(){const overlay=$('#article-reader');if(overlay.hidden)return;overlay.hidden=true;overlay.classList.remove('history-drawer-mode');overlay.innerHTML='';document.body.classList.remove('reader-open');$('#lesson-page').inert=false;$('#toolbar').inert=false;$('#more').focus();}
document.addEventListener('click',e=>{const action=e.target.closest('[data-article-action]');if(action){if(action.dataset.articleAction==='publish')publishArticle();else openArticleReader(action.dataset.articleAction);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#article-reader').hidden){e.preventDefault();closeArticleReader();}},true);
window.addEventListener('hashchange',closeArticleReader);

$('#article-reader').addEventListener('click',e=>{e.stopPropagation();if(e.target.closest('[data-reader-close]'))closeArticleReader();const version=e.target.closest('[data-version]');if(version)showArticleVersion(Number(version.dataset.version));});
$('#article-reader').addEventListener('pointerdown',e=>e.stopPropagation());

function toggleHeaderSearch(open){const search=$('#header-search'),button=$('#search-toggle');search.classList.toggle('is-open',open);$('#header-search-field').hidden=!open;button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Свернуть поиск':'Открыть поиск');if(open)$('#header-search-input').focus();}
$('#search-toggle').addEventListener('click',()=>toggleHeaderSearch(!$('#header-search').classList.contains('is-open')));
$('#header-search').addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();toggleHeaderSearch(false);$('#search-toggle').focus();}if(e.key==='Enter')e.preventDefault();});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#header-search'))toggleHeaderSearch(false);});
